insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 24, 'Filho do homem, diz a ela: Tu não és uma terra limpa, nem molhada de chuva no dia da indignação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 25, 'Há uma conspiração de seus profetas no meio dela, como um leão que brame, que arrebata a presa; devoraram almas, tomam bens e coisas preciosas, aumentam suas viúvas no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 26, 'Seus sacerdotes violentam minha lei, e profanam minhas coisas sagradas; não fazem diferença entre o santo e o profano, nem distinguem o impuro do puro; e escondem seus olhos de meus sábados. Assim eu sou profanado no meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 27, 'Seus príncipes no meio dela são como lobos que arrebatam presa para derramarem sangue, para destruírem almas, para obterem lucro desonesto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 28, 'E seus profetas os rebocam com cal solta, profetizando-lhes falsidade, e adivinhando- lhes mentira, dizendo: Assim diz o Senhor DEUS; sem que o SENHOR tenha falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 29, 'O povo da terra faz graves extorsões, e pratica roubos; fazem violência ao aflito e necessitado, e oprimem sem motivo ao estrangeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 30, 'E busquei dentre eles um homem que tapasse o muro, e que se pusesse na brecha diante de mim pela terra, para que eu não a destruísse; porém a ninguém achei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 22, 31, 'Por isso derramarei sobre eles minha indignação; com o fogo de minha ira os consumirei; retribuirei o caminho deles sobre suas [próprias] cabeças,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 2, 'Filho do homem, houve duas mulheres, filhas de uma [mesma] mãe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 3, 'Estas se prostituíram no Egito; em suas juventudes se prostituíram. Ali foram apertados os seus peitos, e ali foram apalpados os seios de sua virgindade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 4, 'E seus nomes eram: Oolá, a maior, e Oolibá sua irmã; e elas foram minhas, e tiveram filhos e filhas. Estes eram seus nomes: Samaria é Oolá, e Jerusalém Oolibá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 5, 'E Oolá prostituiu-se, mesmo sendo minha; e apaixonou-se por seus amantes, os assírios seus vizinhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 6, 'Vestidos de azul, governadores e príncipes, todos rapazes cobiçáveis, cavaleiros que andavam a cavalo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 7, 'Assim ela cometeu suas prostituições com eles, os quais eram os mais apreciados dos filhos da Assíria, e com todos aqueles por quem ela se apaixonou; contaminou-se com todos os ídolos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 8, 'E não deixou suas fornicações [que trouxe] do Egito; pois com ela se deitaram em sua juventude, e eles apalparam os seios de sua virgindade, e derramaram sua prostituição sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 9, 'Por isso a entreguei na mão de seus amantes, na mão dos filhos da Assíria, por quem tinha se apaixonado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 10, 'Eles descobriram sua nudez, tomaram seus filhos e suas filhas, e a mataram à espada; e veio a ser famosa entre as mulheres, pois fizeram julgamentos contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 11, 'Sua irmã Oolibá viu isso, porém corrompeu sua paixão mais que ela; e suas prostituições foram mais numerosas que as prostituições de sua irmã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 12, 'Apaixonou-se pelos filhos da Assíria, pelos governadores e príncipes, seus vizinhos, vestidos com luxo, cavaleiros que andavam a cavalo, todos eles rapazes cobiçáveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 13, 'E vi que ela estava contaminada; ambas tinham um [mesmo] caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 14, 'E ela aumentou suas prostituições; pois viu homens pintados na parede, as imagens de caldeus pintadas de vermelho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 15, 'Vestidos com cintos ao redor de seus lombos, e enormes turbantes em suas cabeças, tendo todos eles aparência de capitães, à semelhança dos filhos da Babilônia, nascidos na terra da Caldeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 16, 'E apaixonou-se deles logo que seus olhos os viram, e enviou-lhes mensageiros à Caldeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 17, 'Então os filhos da Babilônia vieram até ela à cama dos amores, e a contaminaram com suas prostituições; e ela também se contaminou com eles; então sua alma desgostou deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 18, 'Assim ela expôs suas prostituições, e expôs sua nudez; então minha alma desgostou dela, assim como já tinha desgostado de sua irmã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 19, 'Porém ela multiplicou suas prostituições, relembrando-se dos dias de sua juventude, nos quais havia se prostituído na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 20, 'E apaixonou-se por seus amantes, cuja carne é como carne de asnos, e cujo fluxo é como fluxo de cavalos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 21, 'Assim relembraste a obscenidade de tua juventude, quando os egípcios apalpavam teus peitos, por causa dos seios de tua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 22, 'Portanto, Oolibá, assim diz o Senhor DEUS: Eis que eu levantarei contra ti os teus amantes, dos quais tua alma desgostou, e eu os trarei contra ti ao redor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 23, 'Os filhos da Babilônia, e todos os caldeus, Pecode, Soa, e Coa, todos os filhos da Assíria com eles; rapazes cobiçáveis, governadores e príncipes todos eles, capitães e líderes, todos os que andam a cavalo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 24, 'E virão sobre ti [com] armamentos, carruagens, carretas, e com ajuntamento de povos. Escudos grandes e pequenos, e capacetes serão postos contra ti ao redor; e eu os designarei para que façam o julgamento, e eles te julgarão conforme seus julgamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 25, 'E porei meu zelo contra ti, e te tratarão com furor; tirarão teu nariz e tuas orelhas, e o que restar de ti cairá a espada. Eles tomarão teus filhos e tuas filhas, e o que restar de ti será consumido pelo fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 26, 'Também te despirão de tuas vestes, e tomarão as tuas belas joias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 27, 'Assim farei cessar de ti tua obscenidade e tua prostituição da terra do Egito; e não levantarás mais teus olhos a eles, nem te lembrarás mais do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 28, 'Porque assim diz o Senhor DEUS: Eis que eu te entregarei nas mãos daqueles a quem tu odeias, nas mãos daqueles dos quais tua alma se desgostou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 29, 'Eles te tratarão com ódio, e tomarão todo [o ganho] de teu trabalho, e te deixarão nua e despida; e será exposta a nudez de tuas prostituições, tua obscenidade, e tuas promiscuidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 30, 'Estas coisas serão feitas contigo porque te prostituíste atrás das nações, com as quais te contaminaste com seus ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 31, 'Tu andaste no caminho de tua irmã; por isso darei o cálice dela em tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 32, 'Assim diz o Senhor DEUS: Tu beberás cálice fundo e largo de tua irmã; tu serás motivo de riso e escárnio, pois ele cabe muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 33, 'De embriaguez e de dor tu serás cheia; o cálice de tua irmã Samaria é cálice de medo e de desolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 34, 'Tu, pois, o beberás, o esvaziarás, e quebrarás seus cacos; e arrancarás teus peitos; porque eu falei,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 35, 'Portanto assim diz o Senhor DEUS: Dado que te esqueceste de mim, e me lançaste por trás de tuas costas, por isso, leva tu também [as consequências de] tua obscenidade e [de] tuas prostituições.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 36, 'E disse-me o SENHOR: Filho do homem, julgarás tu a Oolá, e a Oolibá, e lhes denunciarás suas abominações?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 37, 'Pois elas cometeram adultério, e há sangue em suas mãos, e com seus ídolos cometeram adultério; e até a seus filhos que me haviam gerado fizeram passar pelo fogo, para [os] consumir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 38, 'Ainda isto me fizeram: contaminaram meu santuário naquele mesmo dia, e profanaram meus sábados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 39, 'Pois havendo sacrificado seus filhos a seus ídolos, vieram ao meu santuário no mesmo dia para profaná-lo; e eis que assim fizeram em meio da minha casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 40, 'E além disto, mandaram avisar a homens que viriam de longe, aos quais havia sido enviado mensageiro. E eis que vieram; e por causa deles te lavaste, pintaste os teus olhos, e te enfeitaste de joias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 41, 'E te sentaste sobre uma cama luxuosa; diante da qual foi preparada uma mesa, e puseste sobre ela meu perfume e meu óleo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 42, 'E [ouviu-se] nela voz de multidão alegre; e junto dos homens ordinários, foram trazidos os beberrões do deserto; e puseram braceletes em suas mãos, e belas coroas sobre suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 43, 'Então eu disse à envelhecida [em] adultérios: Agora eles se prostituirão com ela, assim como ela [faz] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 44, 'E se deitaram com ela como quem se deita com mulher prostituta; assim se deitaram com Oolá e com Oolibá, mulheres indecentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 45, 'Por isso homens justos as julgarão pela lei que pune as adúlteras, e pela lei que pune as que derramam sangue; pois são adúlteras, e há sangue há nas mãos delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 46, 'Porque assim diz o Senhor DEUS: Farei subir uma multidão contra elas, e as entregarei a terror e ao saque;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 47, 'E a multidão as apedrejará com pedras, e as cortarão com suas espadas; matarão seus filhos e suas filhas, e queimarão com fogo suas casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 48, 'Assim acabarei com a obscenidade da terra, para que todas as mulheres aprendam a não fazer conforme vossa obscenidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 23, 49, 'E porão sobre vós [a culpa por] vossa obscenidade, e levareis os pecados de vossos ídolos; e sabereis que eu sou o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 1, 'No nono ano, no décimo mês, aos dez do mês, veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 2, 'Filho do homem, escreve para ti o nome deste dia, hoje mesmo; [porque] o rei da Babilônia chegou a Jerusalém hoje mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 3, 'E fala uma parábola à casa rebelde, e dize-lhes: Assim diz o Senhor DEUS: Põe uma panela, põe [-a] ,e também deita água dentro dela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 4, 'Ajunta seus pedaços [de carne] nela; todos bons pedaços, pernas e espáduas; enche-a dos melhores ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 5, 'Toma do melhor do rebanho, e acende também os ossos debaixo dela; faze-a ferver bem; e assim seus ossos serão cozidos dentro dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 6, 'Portanto assim diz o Senhor DEUS: Ai da cidade sanguinária, cuja sujeira está nela, e cuja sujeira não saiu dela! Tira dela pedaço por pedaço, não caia sorte sobre ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 7, 'Porque seu sangue está em meio dela; sobre uma pedra exposta ela o pôs; não o derramou sobre a terra, para que fosse coberto com pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 8, 'Para que eu faça subir a ira, para me vingar, eu pus seu sangue sobre a pedra exposta, para que não seja coberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 9, 'Portanto assim diz o Senhor DEUS: Ai da cidade sanguinária! Também eu farei uma grande fogueira,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 10, 'Amontoa lenha, acende o fogo, consome a carne, e a tempera com especiarias; e sejam queimados os ossos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 11, 'Depois põe [a panela] vazia sobre suas brasas, para que se esquente, e seu cobre queime, e se funda sua imundícia no meio dela, e se consuma sua sujeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 12, 'De trabalhos ela [me] cansou, e sua muita sujeira não saiu dela. Sua sujeira [irá] para o fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 13, 'Em tua imundícia há obscenidade, porque eu te purifiquei, porém tu não te purificaste; não mais serás purificada de tua imundícia, enquanto eu não fizer repousar minha ira sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 14, 'Eu, o SENHOR, falei; virá a acontecer, e o farei. Não me tonarei atrás, não pouparei, nem me arrependerei; conforme teus caminhos e teus atos te julgarão, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 15, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 16, 'Filho do homem, eis que com um golpe tirarei de ti o desejo de teus olhos; não lamentes, nem chores, nem escorram de ti lágrimas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 17, 'Geme em silêncio, não faças luto pelos mortos; ata teu turbante sobre ti, e põe teus sapatos em teus pés; e não te cubras os lábios, nem comas pão de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 18, 'E falei ao povo pela manhã, e minha mulher morreu à tarde; e pela manhã fiz como me fora mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 19, 'E o povo me disse: Por acaso não nos farás saber o que [significam] para nós estas coisas que tu estás fazendo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 20, 'Então eu lhes disse: A palavra do SENHOR veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 21, 'Dize à casa de Israel: Assim diz o Senhor DEUS: Eis que eu profanarei meu santuário, a orgulho de vossa fortaleza, o desejo de vossos olhos, e o agrado de vossas almas; e vossos filhos e vossas filhas que deixastes cairão a espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 22, 'E fareis como eu fiz: não cobrireis vossos lábios, nem comereis pão de homens;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 23, 'E vossos turbantes estarão sobre vossas cabeças, e vossos sapatos em vossos pés; não lamentareis nem chorareis, em vez disso vos consumireis por causa de vossas maldades, e gemereis uns com outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 24, 'Assim Ezequiel vos será por sinal; conforme tudo o que ele fez, vós fareis. Quando isto acontecer, então sabereis que eu sou o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 25, 'E tu, filho do homem, por acaso não será no dia que eu lhes tirar sua fortaleza, o seu belo orgulho, o desejo de seus olhos, e o agrado de suas almas, seus filhos e suas filhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 26, 'Que no mesmo dia um que tiver escapado virá a ti para trazer as notícias aos teus ouvidos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 24, 27, 'Naquele dia tua boca se abrirá para falar com o escapado, e falarás, e não ficarás mais calado; e tu lhes serás por sinal, e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 2, 'Filho do homem, dirige tua face contra os filhos de Amom, e profetiza sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 3, 'E diz aos filhos de Amom: Ouvi a palavra do Senhor DEUS; assim diz o Senhor DEUS: Dado que disseste: Ha, ha! Acerca de meu santuário quando foi profanado, e acerca da terra de Israel quando foi desolada, e acerca da casa de Judá quando foram ao cativeiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 4, 'Por isso, eis, eu te entregarei como possessão aos filhos do oriente, e estabelecerão suas acampamentos em ti, e porão suas tendas em ti; eles comerão teus frutos e beberão teu leite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 5, 'E tornarei a Rabá em estábulo de camelos, e os filhos de Amom em curral de ovelhas; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 6, 'Porque assim diz o Senhor DEUS: Dado que bateste palmas, e bateste o pés, e te alegraste na alma em todo teu desprezo sobre a terra de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 7, 'Por isso, eis que eu estenderei minha mão contra ti, e te entregarei às nações para seres saqueada; e eu te cortarei dentre os povos, e te destruirei dentre as terras; eu te eliminarei, e saberás que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 8, 'Assim diz o Senhor DEUS: Visto que Moabe e Seir dizem: Eis que a casa de Judá é como todas as nações,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 9, 'Por isso, eis que abrirei a lateral de Moabe desde as cidades, desde suas cidades que estão em suas fronteiras, as melhores terras: Bete-Jesimote, e Baal-Meom, e até Quiriataim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 10, 'Serão para os filhos do oriente, com [a terra] dos filhos de Amom; e a entregarei por possessão, para que não haja lembrança dos filhos de Amom entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 11, 'Também farei julgamentos em Moabe; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 12, 'Assim diz o Senhor DEUS: Dado que Edom se vingou contra a casa de Judá, e se tornaram extremamente culpados ao se vingarem deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 13, 'Por isso assim diz o Senhor DEUS: Eu também estenderei minha mão contra [a terra de] Edom: exterminarei dela homens e animais, e a tornarei desolada; desde Temã e Dedã cairão à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 14, 'E me vingarei contra Edom pela mão do meu povo Israel; e farão em Edom segundo minha ira, e conhecerão minha vingança, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 15, 'Assim diz o Senhor DEUS: Dado que os filisteus agiram com vingança, quando se vingaram com desprezo na alma, destruindo por hostilidades antigas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 16, 'Por isso assim diz o Senhor DEUS: Eis que eu estendo minha mão contra os filisteus, e exterminarei os queretitas, e destruirei o resto da costa do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 25, 17, 'E farei neles grandes vinganças, com castigos de furor; e saberão que eu sou o SENHOR, quando me vingar deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 1, 'E sucedeu no décimo primeiro ano, no primeiro [dia] do mês, que veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 2, 'Filho do homem, dado que Tiro falou sobre Jerusalém: Ha, ha!, quebrada está a porta das nações; ela se virou para mim; eu me encherei [de riquezas] ,[agora] que ela está assolada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 3, 'Por isso, assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Tiro; e farei subir contra ti muitas nações, tal como o mar faz subir suas ondas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 4, 'E demolirão os muros de Tiro, e derrubarão suas torres; varrerei dela seu pó, e a deixarei como uma rocha exposta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 5, 'Servirá para estender redes no meio do mar, porque [assim] eu falei,diz o Senhor DEUS; e será saqueada pelas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 6, 'E suas filhas que estiverem no campo serão mortas à espada; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 7, 'Porque assim diz o Senhor DEUS: Eis que desde o norte eu trarei contra Tiro a Nabucodonosor, rei da Babilônia, rei de reis, com cavalos, carruagens, cavaleiros, tropas, e muito povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 8, 'Tuas filhas no campo ele matará à espada; e porá contra ti fortalezas, fará cerco contra ti, e levantará escudos contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 9, 'E fará aríetes baterem contra teus muros, e derrubará tuas torres com suas espadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 10, 'Com a multidão de seus cavalos o pó deles te cobrirá; teus muros tremerão com o estrondo dos cavaleiros, das rodas, e das carruagens, quando ele entrar por tuas portas como quem entra por uma cidade em ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 11, 'Com as unhas de seus cavalos pisará todas as tuas ruas; matará teu povo à espada, e as colunas de tua fortaleza cairão por terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 12, 'E roubarão tuas riquezas, e saquearão tuas mercadorias; derrubarão teus muros, e arruinarão tuas preciosas casas; e lançarão tuas pedras, tua madeira e teu pó no meio das águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 13, 'E farei cessar o ruído de tuas canções, e o som de tuas harpas não será mais ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 14, 'E te farei como uma rocha exposta; servirás para estender redes; e nunca mais serás reconstruída; porque eu, o SENHOR falei,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 15, 'Assim diz o Senhor DEUS a Tiro: Por acaso não se estremecerão as ilhas com o estrondo de tua queda, quando os feridos gemerem, quando houver grande matança no meio de ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 16, 'Então todos os príncipes do mar descerão de seus tronos, tirarão de si seus mantos, e despirão suas roupas bordadas; com tremores se vestirão, sobre a terra se sentarão, e estremecerão em todo momento, e ficarão espantados por causa de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 17, 'E levantarão lamentação por causa de ti, e te dirão: Como pereceste tu, povoada dos mares, famosa cidade, que foi forte no mar; ela e seus moradores, que punham seu espanto a todos os moradores dela?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 18, 'Agora as terras costeiras se estremecerão no dia de tua queda; e as ilhas que estão no mar se espantarão com o teu fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 19, 'Porque assim diz o Senhor DEUS: Quando eu te tornar uma cidade desolada, como as cidades que não se habitam; quando eu fizer subir sobre ti um abismo, e muitas águas te cobrirem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 20, 'Então eu te farei descer com os que descem à cova, junto dos povos do passado; e te porei nas profundezas da terra, como os lugares desertos antigos, com os que descem à cova, para que não sejas habitada; então darei glória na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 26, 21, 'Eu te tonarei em espanto, e não mais existirás; e ainda que te busquem, nunca mais serás achada,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 2, 'Tu, pois, filho do homem, levanta uma lamentação sobre Tiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 3, 'E dize a Tiro, que habita nas entradas do mar, e faz comércio com dos povos em muitas terras costeiras: Assim diz o Senhor DEUS: Ó Tiro, tu dizes: Eu sou perfeita em beleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 4, 'Teus limites estão no coração dos mares; os que te edificaram aperfeiçoaram a tua beleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 5, 'Fabricaram todos os teus conveses com faias de Senir; trouxeram cedros do Líbano para fazerem mastros para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 6, 'Fizeram teus remos [com] carvalhos de Basã; fizeram teus bancos com ciprestes das ilhas do Chipre, unidos com marfim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 7, 'Linho bordado do Egito era tua cortina, para te servir de vela; de azul e púrpura das ilhas de Elisá era teu toldo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 8, 'Os moradores de Sidom e de Arvade eram teus remadores; teus sábios, ó Tiro, [que] estavam em ti, eles foram teus pilotos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 9, 'Os anciãos de Gebal e seus sábios eram em ti os que reparavam tuas fendas; todos os navios do mar e seus marinheiros delas foram em ti para negociar tuas mercadorias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 10, 'Persas e lídios, e os de Pute, eram em teu exército teus soldados; escudos e capacetes penduraram em ti; eles te deram tua pompa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 11, 'Os filhos de Arvade e teu exército estavam sobre teus muros ao redor, e os gamaditas em tuas torres; penduravam seus escudos sobre teus muros ao redor; eles aperfeiçoavam tua beleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 12, 'Társis negociava contigo, por causa da abundância de todas as variedades de riquezas; com prata, ferro, estanho, e chumbo, negociavam [em] tuas feiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 13, 'Javã, Tubal, e Meseque eram teus mercadores; com almas humanas e com vasos de metal, fizeram negócios contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 14, 'Da casa de Togarma traziam cavalos, cavaleiros e mulos, para tuas feiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 15, 'Os filhos de Dedã eram teus mercadores; muitas ilhas eram o comércio sob teu controle; chifres de marfim e madeira de ébano te deram como presente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 16, 'A Síria negociava contigo por causa da abundância de tuas obras; turquesas, púrpura, materiais bordados, linhos finos, corais, e rubis, traziam em tuas feiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 17, 'Eles, Judá e a terra de Israel, eram teus mercadores; com trigo de Minite, e panague, mel, e azeite, e resina, fizeram negócios contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 18, 'Damasco negociava contigo, por causa da abundância de tuas obras, pela abundância de todas as variedades de bens; com vinho de Helbom, e lã branca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 19, 'Também Dã e Javã de Uzal comercializavam em tuas feiras; ferro lavrado, cássia, e cana aromática havia em teu comércio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 20, 'Dedã negociava contigo, com panos preciosos para carros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 21, 'A Arábia, e todos os príncipes de Quedar, eles eram mercadores sob teu controle; com cordeiros, carneiros, e bodes; nestas coisas negociavam contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 22, 'Os mercadores de Sabá e de Raamá eram teus mercadores; com toda especiaria importante, toda pedra preciosa, e ouro, comercializavam em tuas feiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 23, 'Harã, Cané, e Éden, os mercadores de Sabá, da Assíria, e Quilmade negociavam contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 24, 'Estes negociavam contigo em toda variedade de mercadorias: com tecidos azuis, com bordados, e com caixas de roupas preciosas, amarradas com cordões, e [postos] em cedro, em teu comércio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 25, 'Os navios de Társis transportavam os artigos do teu negócio; e te encheste, e te tornaste muito pesada no meio dos mares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 26, 'Teus remadores te trouxeram a muitas águas; o vento oriental te quebrou no meio dos mares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 27, 'Tuas riquezas, tuas feiras, teu negócio, teus marinheiros, teus pilotos; os que reparavam tuas fendas, teus comerciantes, e todos teus soldados que há em ti, com toda a tua companhia que está no meio de ti, cairão no meio dos mares, no dia de tua queda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 28, 'Ao estrondo das vozes de teus marinheiros tremerão os arredores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 29, 'E todos os que usam remo; marinheiros, e todos os pilotos do mar descerão de seus navios, e pararão na terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 30, 'E farão ouvir sua voz sobre ti; gritarão amargamente, lançarão pó sobre suas cabeças, e se revolverão na cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 31, 'E se farão calvos por causa de ti, se vestirão de sacos, e chorarão por ti com amargura da alma, com amarga lamentação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 32, 'E levantarão lamentação sobre em seu pranto, e lamentarão sobre ti dizendo: Quem foi como Tiro, como a [que agora está] silenciada no meio do mar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 33, 'Quando tuas mercadorias vinham dos mares, fartaste muitos povos; enriqueceste os reis da terra com a abundância de tuas riquezas e de teus negócios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 34, 'Agora foste quebrada dos mares, nas profundezas das águas; caíram teu negócio e toda a tua companhia no meio de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 35, 'Todos os moradores dos litorais foram espantados por causa de ti, e seus reis ficaram horrorizados; seus rostos se conturbaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 27, 36, 'Os mercadores nos povos assoviam por causa de ti; tu te tornaste em motivo de espanto, e nunca mais voltarás a existir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 2, 'Filho do homem, dize ao príncipe de Tiro: Assim diz o Senhor DEUS: Dado que teu coração se exalta, e dizes: Eu sou um deus; no trono de de Deus me sento no meio dos mares (sendo tu homem e não Deus); e consideras teu coração como coração de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 3, '(Eis que tu és mais sábio que Daniel; não há segredo algum que possa se esconder de ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 4, 'Com tua sabedoria e teu entendimento obtiveste riquezas, e adquiriste ouro e prata em teus tesouros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 5, 'Com a tua grande sabedoria aumentaste tuas riquezas em teu comércio; e por causa de tuas riquezas teu coração tem se exaltado).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 6, 'Portanto assim diz o Senhor DEUS: Dado que consideras teu coração como coração [se fosse] de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 7, 'Por isso eis que eu trarei sobre ti estrangeiros, os mais violentos das nações, os quais desembainharão suas espadas contra a beleza de tua sabedoria, e contaminarão o teu resplendor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 8, 'À cova te farão descer, e morrerás da morte dos que morrem no meio dos mares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 9, 'Por acaso dirás: Eu sou Deus, diante de teu matador? Tu és homem, e não Deus, nas mãos de quem te matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 10, 'De morte de incircuncisos morrerás, pela mão de estrangeiros; porque [assim] eu falei, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 11, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 12, 'Filho do homem, levanta uma lamentação sobre o rei de Tiro, e dize-lhe: Assim diz o Senhor DEUS: Tu eras o carimbo da perfeição, cheio de sabedoria, e perfeito em formosura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 13, 'Estiveste no Éden, o jardim de Deus; toda pedra preciosa era tua cobertura; sárdio, topázio, diamante, turquesa, ônix, jaspe, safira, carbúnculo, e esmeralda; e [de] ouro era a obra de tuas molduras e de teus engastes em ti; no dia em que foste criado estavam preparados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 14, 'Tu eras querubim ungido, cobridor; e eu te estabeleci, no santo monte de Deus estavas; no meio de pedras de fogo tu andavas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 15, 'Íntegro eras em teus caminhos, desde o dia em que foste criado, até que se achou maldade em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 16, 'Pela abundância de teu comércio encheram o meio de ti de violência; por isso eu te expulsei como profanado do monte de Deus, e te farei perecer, ó querubim cobridor, do meio das pedras de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 17, 'Teu coração se exaltou por causa de tua formosura, corrompeste tua sabedoria por causa de teu resplendor; eu te lancei por terra; diante dos reis eu te pus, para que olhem para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 18, 'Por causa da multidão de tuas maldades e da perversidade de teu comércio, profanaste teus santuários; por isso eu fiz sair um fogo do meio de ti, o qual te consumiu; e te tornei em cinza sobre a terra, diante dos olhos de todos quantos te veem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 19, 'Todos os que te conhecem entre os povos estão espantados por causa de ti; em grande horror te tornaste, e nunca mais voltarás a existir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 20, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 21, 'Filho do homem, dirige teu rosto contra Sidom, e profetiza contra ela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 22, 'E dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Sidom, e serei glorificado no meio de ti; e saberão que eu sou o SENHOR, quando nela fizer juízos, e nela me santificar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 23, 'Pois enviarei a ela pestilência e sangue em suas ruas; e mortos cairão no meio dela pela espada que está contra ela ao redor; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 24, 'E a casa de Israel nunca mais terá espinho que a fira, nem abrolho que cause dor, de todos os que desprezam ao redor deles; e saberão que eu sou o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 25, 'Assim diz o Senhor DEUS: Quando eu ajuntar a casa de Israel dos povos entre os quais estão dispersos, e eu me santificar entre eles diante dos olhos das nações, então habitarão em sua terra, que dei a meu servo Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 28, 26, 'E habitarão nela em segurança, edificarão casas, e plantarão vinhas; e habitarão em segurança, quando eu fizer juízos contra todos os que os desprezam ao redor deles; e saberão que eu sou o SENHOR, o Deus deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 1, 'No décimo ano, no décimo mês, aos doze do mês, veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 2, 'Filho do homem, dirige teu rosto contra Faraó, rei do Egito; e profetiza contra ele e contra todo o Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 3, 'Fala, e dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, Faraó rei do Egito, o grande dragão que jaz no meio de seus rios, que diz: Meu rio é meu, eu [o] fiz para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 4, 'Porém eu porei anzóis em teus queixos, e apegarei os peixes de teus rios a tuas escamas, e te tirarei do meio de teus rios, e todos os peixes de teus rios se apegarão a tuas escamas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 5, 'E te deixarei no deserto, a ti e a todos os peixes de teus rios; sobre a face do campo aberto cairás; não serás recolhido, nem ajuntado; para os animais da terra e para as aves do céu te dei por alimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 6, 'E todos os moradores do Egito saberão que eu sou o SENHOR, pois foram um bordão de cana para a casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 7, 'Quando eles te tomaram pela mão, te quebraste, e lhes rompeste todo os ombros; e quando se recostaram a ti, te quebraste, e lhes fizeste instáveis todos os lombos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 8, 'Portanto, assim diz o Senhor o SENHOR: Eis que eu trarei contra ti espada, e destruirei de ti homens e animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 9, 'E a terra do Egito se tornará desolada e deserta; e saberão que eu sou o SENHOR; porque ela disse: O rio é meu, eu o fiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 10, 'Portanto eis que eu sou contra ti, e contra teus rios; e tornarei a terra do Egito em desertas e assoladas solidões, desde Migdol e Sevene, até o limite de Cuxe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 11, 'Não passará por ela pé de homem, nem pata de animal passará por ela; nem será habitada por quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 12, 'Porque tornarei a terra do Egito em desolação, em meio a terras desoladas; e suas cidades no meio das cidades desertas ficarão desoladas por quarenta anos; e espalharei os egípcios entre as nações, e os dispersarei pelas terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 13, 'Porém assim diz o Senhor DEUS: Ao fim de quarenta anos ajuntarei os egípcios dos povos entre os quais forem espalhados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 14, 'E restaurarei o Egito de seu infortúnio, e os trarei de volta à terra de Patros, à terra de seu nascimento; e ali serão um reino inferior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 15, 'Será mais inferior que os [outros] reinos; e nunca mais se erguerá sobre as nações; porque eu os diminuirei, para que não dominem as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 16, 'E não será mais motivo de confiança para a casa de Israel, para fazê-la lembrar de [sua] maldade, quando olharam para eles; e saberão que eu sou o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 17, 'E sucedeu no ano vinte e sete, no primeiro [mês] ,no primeiro [dia] do mês, que veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 18, 'Filho do homem, Nabucodonosor rei da Babilônia mobilizou seu exército para uma grande campanha contra Tiro. Toda cabeça se tornou calva, e todo ombro se despelou; porém não houve ganho para ele nem para seu exército pela campanha que executou contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 19, 'Portanto assim diz o Senhor DEUS: Eis que eu darei a Nabucodonosor, rei da Babilônia, a terra do Egito; e ele levará sua riqueza, tomará seus despojos, e saqueará sua presa, e [isto] será o ganho para seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 20, 'Como pagamento por seu trabalho que executou contra ela, eu lhe dei a terra do Egito; porque trabalharam por mim,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 29, 21, 'Naquele dia farei crescer o poder da casa de Israel, e te darei abertura de boca no meio deles; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 2, 'Filho do homem, profetiza, e dize: Assim diz o Senhor DEUS: Gritai: Ai daquele dia!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 3, 'Porque perto está o dia, perto está o dia do Senhor; dia de nuvens; será o tempo das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 4, 'E a espada virá ao Egito, e haverá grande dor em Cuxe, quando caírem os mortos no Egito; e tomarão sua multidão, e serão destruídos seus fundamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 5, 'Cuxe, Pute, Lude, e todo o povo misturado, e Cube, e os filhos da terra do pacto cairão com eles à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 6, 'Assim diz o SENHOR: Também cairão os que sustentam ao Egito, e a soberba de sua força irá abaixo; desde Migdol e Sevene cairão nele à espada, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 7, 'E serão assolados no meio das terras assoladas, e suas cidades estarão no meio das cidades desertas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 8, 'E saberão que eu sou o SENHOR, quando puser fogo ao Egito, e forem destruídos todos os que o ajudavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 9, 'Naquele dia sairão de diante de mim mensageiros em navios, para espantarem a confiante Cuxe, e haverá grandes dores neles, como no dia do Egito; porque eis que está vindo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 10, 'Assim diz o Senhor DEUS: Farei cessar a multidão do Egito pela mão de Nabucodonosor, rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 11, 'Ele, e com ele seu povo, os mais terríveis das nações, serão trazidos para destruir a terra; e desembainharão suas espadas contra o Egito, e encherão a terra de mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 12, 'E secarei os rios, entregarei a terra em mãos de malignos, e destruirei a terra e tudo o que ela contém pela mão de estrangeiros; eu, o SENHOR falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 13, 'Assim diz o Senhor DEUS: Também destruirei aos ídolos, e darei fim às imagens idolátricas de Mênfis; não haverá mais príncipe da terra do Egito, e porei medo na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 14, 'E desolarei a Patros, porei fogo a Zoã, e farei juízos em Nô.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 15, 'E derramarei minha ira sobre Pelúsio, a fortaleza do Egito, e exterminarei a multidão de Nô.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 16, 'E porei fogo ao Egito; Pelúsio terá grande dor, Nô será destroçada, e Mênfis terá angústias contínuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 17, 'Os rapazes de Áven e de Pibesete cairão à espada; e elas irão em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 18, 'E em Tafnes o dia se escurecerá, quando eu quebrar ali o jugo do Egito, e nela cessar a soberba de sua força; uma nuvem a cobrirá, e suas filhas irão em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 19, 'Pois farei julgamentos no Egito, e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 20, 'E sucedeu no décimo primeiro ano, no primeiro [mês] , aos sete do mês, que veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 21, 'Filho do homem, quebrei o braço de Faraó, rei do Egito; e eis que não será enfaixado com remédios, nem lhe porão faixa para o envolver, a fim de curá-lo para que possa segurar espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 22, 'Portanto, assim diz o Senhor DEUS: Eis que sou contra Faraó, rei do Egito, e quebrarei seus braços, tanto o forte como o quebrado; e farei cair a espada de sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 23, 'E espalharei os egípcios entre as nações, e os dispersarei pelas terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 24, 'E fortalecerei os braços do rei da Babilônia, e porei minha espada em sua mão; porém quebrarei os braços de Faraó, e diante dele gemerá com gemidos de ferido de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 25, 'Fortalecerei, pois, os braços do rei de Babilônia, enquanto que os braços de Faraó cairão; e saberão que eu sou o SENHOR, quando eu tiver posto minha espada na mão do rei da Babilônia, e ele a estender sobre a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 30, 26, 'E espalharei os egípcios entre as nações, e os dispersarei pelas terras; assim saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 1, 'E sucedeu, no décimo primeiro ano, no terceiro [mês] , ao primeiro [dia] do mês, que veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 2, 'Filho do homem, diz a Faraó, rei do Egito, e à sua multidão: A quem és semelhante na tua grandeza?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 3, 'Eis que a Assíria era um cedro do Líbano, de belos ramos, com grande sombra de sua folhagem, e de alta estatura; seu topo estava entre ramos espessos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 4, 'As águas o nutriam, as profundezas o faziam crescer; correntes corriam ao redor de onde estava plantada, e enviava seus ribeiros a todas as árvores do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 5, 'Por isso sua altura se elevou acima de todas as árvores do campo; seus galhos se multiplicaram, e seus ramos se alongavam, por causa das muitas águas enviadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 6, 'Todas as aves do céus faziam ninhos em seus galhos, e todos os animais do campo geravam debaixo de seus ramos; e todos os grandes povos habitavam à sua sombra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 7, 'Assim era ele, belo em sua grandeza, na extensão de seus ramos; porque sua raiz estava junto a muitas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 8, 'Os cedros não o encobriram no jardim de Deus; as faias não igualavam os seus galhos, nem os plátanos eram semelhantes a seus ramos; nenhuma árvore no jardim de Deus se assemelhava a ele em sua beleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 9, 'Eu o fiz belo com a multidão de seus ramos; e todas as árvores do Éden, que estavam no jardim de Deus, tiveram inveja dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 10, 'Portanto, assim diz o Senhor DEUS: Visto que te elevaste em estatura, e seu topo se elevou no meio de ramos espessos, e seu coração se exaltou na sua altura,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 11, 'Por isso eu o entreguei na mão do mais poderoso das nações, para que o tratasse como merece; pela sua perversidade eu o lancei fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 12, 'Estrangeiros da mais terrivel das nações o cortaram e o deixaram; seus ramos caíram sobre os montes e por todos os vales, e seus galhos foram quebrados por todas as correntes de águas da terra; e todos os povos da terra se retiraram de sua sombra, e o deixaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 13, 'Todas as aves do céu habitaram sobre sua ruína, e todos os animais do campo se ficaram sobre seus ramos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 14, 'Para que todas as árvores próximas das águas não se elevem na sua estatura, nem levantem o seu topo no meio dos ramos espessos, e que todas as que bebem águas não confiem em si mesmas por sua altura; porque todas estão entregues à morte, até debaixo da terra, no meio dos filhos dos homens, com os que vão para a cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 15, 'Assim diz o Senhor DEUS: No dia em que ele desceu ao Xeol, eu fiz que houvesse luto, fiz cobrir as profundezas por sua causa; detive suas correntes, e as muitas águas foram retidas; cobri o Líbano de trevas por causa dele, e por sua causa todas as árvores do campo definharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 16, 'Do estrondo de sua queda eu fiz tremer as nações, quando o fiz descer ao Xeol com os que descem à cova; e todas as árvores de Éden, as preferidas e melhores do Líbano, todas as que bebem águas, consolaram-se debaixo da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 17, 'Também desceram com ele ao Xeol, com os mortos à espada, e os que foram seus apoiadores, os que habitavam à sua sombra no meio das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 31, 18, 'Quem se assemelha a ti em glória e em grandeza entre as árvores do Éden? Porém serás derrubado com as árvores do Éden para debaixo da terra; jazerás entre os incircuncisos, com os mortos à espada. Este é Faraó e toda a sua multidão, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 1, 'E sucedeu no décimo segundo ano, no décimo segundo mês, no primeiro [dia] do mês, que veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 2, 'Filho do homem, levanta uma lamentação sobre Faraó, rei do Egito, e dize-lhe: Tu te comparavas a um jovem leão [entre] as nações, porém tu eras como um monstro marinho nos mares, que te contorcias em teus rios, e turbavas as águas com teus pés, e enlameavas seus rios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 3, 'Assim diz o Senhor DEUS: Portanto estenderei sobre ti minha rede com ajuntamento de muitos povos, e te puxarão para cima em minha rede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 4, 'Então te deixarei em terra, não campo aberto eu te lançarei; e farei que com que fiquem sobre ti todas as aves do céu, e fartarei de ti os animais de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 5, 'E porei tua carne sobre os montes, e encherei os vales com tua altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 6, 'E regarei com teu sangue a terra onde nadas, até os montes; e as correntes se encherão de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 7, 'E quando eu te extinguir, cobrirei os céus, e farei escurecer suas estrelas; cobrirei o sol cobrirei com nuvem, e a lua não fará brilhar sua luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 8, 'Todas os luminares de luz no céu escurecerei sobre ti, e trarei trevas sobre tua terra,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 9, 'E perturbarei o coração de muitos povos, quando levarei a tua destruição entre as nações, a terras que tu não conheceste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 10, 'E farei com que muitos povos fiquem espantados por causa de ti, e seus reis se encham de medo por causa de ti, quando eu mover minha espada diante de seus rostos; e todos se estremecerão, cada um em sua alma, em todo momento, no dia de tua queda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 11, 'Porque assim diz o Senhor DEUS: A espada do rei da Babilônia virá sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 12, 'Farei cair tua multidão com as espadas dos guerreiros, todos eles são os mais terríveis das nações; e destruirão a soberba do Egito, e toda sua multidão será destruída.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 13, 'E destruirei todas os seus animais de sobre as muitas águas; nem mais as turbará pé de homem, nem unha de animais as turbarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 14, 'Então farei suas águas se assentarem, e farei seus rios fluírem como azeite,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 15, 'Quando eu tornar a terra do Egito em desolação, e a terra for desolada de tudo que ela tem, quando eu ferir a todos os que nela moram, então saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 16, 'Esta é a lamentação que lamentarão; as filhas das nações a lamentarão; por causa do Egito e de toda a sua multidão a lamentarão,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 17, 'E sucedeu no décimo segundo ano, aos quinze do mês, que veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 18, 'Filho do homem, pranteia sobre a multidão do Egito, e faze-a descer, a ela e às vilas das nações pomposas, nas profundezas da terra, com os que descem à cova:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 19, 'Por acaso és tu mais belo que os outros? Desce, e deita-te com os incircuncisos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 20, 'Entre os mortos à espada cairão; para a espada está entregue; arrastai a ela e a toda a sua multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 21, 'Do meio do Xeol os mais poderosos dos guerreiros, com os seus ajudadores, lhe falarão: Desceram; os incircuncisos jazeram, mortos à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 22, 'Ali está a Assíria com toda a sua companhia; em redor dele estão os seus sepulcros; todos eles foram mortos, que caíram pela espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 23, 'Seus sepulcros foram postos do lado da cova, e sua companhia está ao redor de seu sepulcro; todos eles foram mortos, caídos pela espada, e causaram terror na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 24, 'Ali está Elão com toda a sua multidão ao redor de seu sepulcro; todos eles foram mortos, caídos pela espada, os quais desceram incircuncisos às profundezas da terra, os quais causaram terror deles na terra dos viventes, porém levaram sua vergonha com os que desceram à cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 25, 'No meio dos mortos lhe puseram uma cama com toda a sua multidão; ao redor dele estão seus sepulcros: todos eles são incircuncisos, mortos pela espada, porque o terror deles se espalhou pela terra dos viventes, porém levaram sua vergonha com os que descem à cova; no meio dos mortos foi posto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 26, 'Ali está Meseque e Tubal, com toda a sua multidão; ao redor dele estão seus sepulcros; todos eles são incircuncisos, mortos pela espada, porque causaram terror deles na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 27, 'Porém não jazerão com os guerreiros que caíram dos incircuncisos, os quais desceram ao Xeol com suas armas de guerra, e puseram suas espadas debaixo de suas cabeças; mas suas maldades estarão sobre seus ossos, porque foram o terror dos guerreiros na terra dos viventes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 28, 'Também tu serás quebrado no meio dos incircuncisos, e jazerás com os mortos à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 29, 'Ali está Edom, seus reis e todos os seus príncipes, os quais com sua força foram postos com os mortos à espada; estes jazem com os incircuncisos, e com os que desceram à cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 30, 'Ali estão os príncipes do norte, todos eles, e todos os sidônios, que desceram com os mortos, que foram envergonhados pelo terror de seu poder, e jazem incircuncisos com os mortos à espada, e levam sua vergonha com os que desceram à cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 31, 'Faraó os verá, e se consolará com toda a sua multidão; Faraó com todo seu exército, mortos à espada,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 32, 32, 'Porque eu causei meu terror na terra dos viventes; por isso jazerá no meio dos incircuncisos, com os mortos a espada, Faraó e toda a sua multidão,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 2, 'Filho do homem, fala aos filhos de teu povo, e dize-lhes: Quando eu trouxer espada sobre a terra, e o povo da terra tomar um homem de seu próprio território, e puser como seu vigilante,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 3, 'E ele vir que a espada está vindo sobre a terra, e tocar trombeta, e alertar ao povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 4, 'Se alguém ouvir o som da trombeta, e não der atenção ao alerta, quando a espada vier, e o tomar, seu sangue será sobre sua própria cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 5, 'Ouviu o som da trombeta, e não deu atenção ao alerta; seu sangue será sobre ele; mas o que der atenção ao alerta salvará sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 6, 'Porém se o vigilante vir que a espada está vindo, e não tocar a trombeta, e o povo não for alertado, e a espada vier, e tomar alguém do [povo] ,por causa de sua maldade foi tomado, mas exigirei seu sangue da mão do vigilante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 7, 'A ti, pois, filho do homem, eu te pus como vigilante para casa de Israel; por isso ouvirás a palavra de minha boca, e os alerta de minha parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 8, 'Quando eu disser ao perverso: Ó perverso, certamente morrerás; se tu não falares para o perverso se dissuadir de seu caminho, o perverso morrerá por sua maldade, mas exigirei o sangue dele de tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 9, 'Mas quando tu alertares ao perverso de seu caminho, para que dele se converta, e ele não se converter de seu caminho, ele morrerá em sua maldade, porém tu livraste tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 10, 'Portanto tu, filho do homem, dize à casa de Israel: Assim vós tendes falado: Nossas transgressões e nossos pecados estão sobre nós, e por causa deles estamos desfalecendo; como então viveremos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 11, 'Dize-lhes: Vivo eu, diz o Senhor DEUS, que não tenho prazer na morte do perverso, mas sim em que o perverso se converta de seu caminho, e viva. Convertei-vos! Convertei-vos de vossos caminhos; por que razão morrereis, ó casa de Israel?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 12, 'Portanto tu, filho do homem, dize aos filhos de teu povo: A justiça do justo não o livrará no dia em que ele transgredir; e quanto à perversidade do perverso não o fará cair no dia em que ele se converter de sua perversidade; e o justo não poderá viver por sua [justiça] , no dia que pecar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 13, 'Quando eu ao justo: Certamente viverá, e ele, confiante em sua justiça, passar a praticar perversidade, todas suas justiças não serão lembradas, mas na perversidade que fez, por ela morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 14, 'E quando eu disser ao perverso: Certamente morrerás; se ele se converter de seu pecado, e praticar juízo e justiça,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 15, 'Se o perverso restituir o penhor, devolver o que tiver roubado, e caminhar nos estatutos da vida, não fazendo maldade, certamente viverá; não morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 16, 'Nenhum de seus pecados que tinha cometido lhe será lembrado; praticou juízo e justiça; certamente viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 17, 'Porém os filhos de teu povo dizem: Não é correto o caminho do Senhor; é o caminho deles que não é correto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 18, 'Se o justo se desviar de sua justiça, e fizer perversidade, por causa dela morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 19, 'E se o perverso se converter de sua perversidade, e passar a praticar juízo e justiça, por causa deles viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 20, 'Porém dizeis: Não é correto o caminho do Senhor. Eu vos julgarei a cada um conforme seus [próprios] caminhos, ó casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 21, 'E aconteceu no décimo segundo ano de nosso cativeiro, no décimo [mês] , aos cinco do mês, que veio a mim um que havia escapado de Jerusalém, dizendo: A cidade já foi ferida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 22, 'Ora, a mão do SENHOR estivera sobre mim à tarde, antes que o escapado viesse, e abrira minha boca, até que chegou a mim pela manhã; e minha boca se abriu, e nunca mais fiquei mudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 23, 'Então veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 24, 'Filho do homem, os moradores destes lugares arruinados na terra de Israel, falando o seguinte: Abraão era um só, e tomou posse da terra; porém nós somos muitos; esta terra nos foi dada por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 25, 'Portanto dize-lhes: Assim diz o Senhor DEUS: Comeis com sangue, levantais vossos olhos a vossos ídolos, e derramais sangue; e possuireis a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 26, 'Confiais em vossas espadas, cometeis abominação, e contaminais cada um a mulher de seu próximo; e possuireis a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 27, 'Tu lhes dirás assim: Assim diz o Senhor DEUS: Vivo eu, que os que estiverem em lugares arruinados cairão à espada, e ao que estiver sobre a face do campo entregarei às feras, para que o devorem; e os que estão em fortalezas e em cavernas morrerão de pestilência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 28, 'Porque tornarei a terra em desolação e ruínas, e a soberba de sua força cessará; e os montes de Israel serão desolados de tal maneira que ninguém passe [por eles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 29, 'Então saberão que eu sou o SENHOR, quando eu tornar a terra em desolação e ruínas, por causa de todas as suas abominações que fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 30, 'E tu, ó filho do homem, os filhos de teu povo falam de ti junto às paredes e às portas das casas, e um fala com o outro, cada um com seu irmão, dizendo: Vinde, pois, e ouvi que palavra vem do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 31, 'E eles vem a ti, como o povo costuma vir, e se sentam diante de ti [como se fosse] meu povo, e ouvem tuas palavras, mas não as praticam; em vez disso lisonjeiam com suas bocas, [porém] seus corações buscam o interesse próprio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 32, 'E eis que tu és para eles como um cantor de amores, de bela voz e que canta bem; então ouvem tuas palavras, mas não as praticam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 33, 33, 'Porém quando isso vier a acontecer (eis que virá) saberão que houve profeta no meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 2, 'Filho do homem, profetiza contra os pastores de Israel; profetiza, e dize-lhes, aos pastores: Assim diz o Senhor DEUS: Ai dos pastores de Israel, que se apascentam a si mesmos! Por acaso não devem os pastores apascentarem as ovelhas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 3, 'Comeis a gordura, e vos vestis da lã; degolais o cevado, [porém] não apascentais as ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 4, 'Não fortaleceis as fracas, nem curais a doente; não pondes curativo na que está ferida; não trazeis de volta a desgarrada, e a perdida não buscais; porém dominais sobre elas com rigor e dureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 5, 'Assim se espalharam, porque não há pastor; e se tornaram alimento para toda fera do campo, porque se espalharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 6, 'Minhas ovelhas andaram sem rumo por todos os montes, e em todo morro alto; minhas ovelhas foram espalhadas por toda a face da terra, e ninguém há que as procure, ninguém que as busque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 7, 'Por isso, ó pastores, ouvi a palavra do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 8, 'Vivo eu, diz o Senhor DEUS, que dado que minhas ovelhas foram [entregues] ao saque, e minhas ovelhas serviram de alimento para toda fera do campo, por não haver pastor; e meus pastores não procuram minhas ovelhas, ao invés disso apascentaram a si mesmos, e não apascentam minhas ovelhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 9, 'Por isso, ó pastores, ouvi a palavra do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 10, 'Assim diz o Senhor DEUS: Eis que eu sou contra os pastores; exigirei deles minhas ovelhas, e farei com que cessem de apascentar as ovelhas; e os pastores não apascentarão mais a si mesmos; pois eu livrarei minhas ovelhas da boca deles, e elas não [mais] lhes servirão de alimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 11, 'Porque assim diz o Senhor DEUS: Eis que eu, eu mesmo, procurarei minhas ovelhas, e as buscarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 12, 'Assim como o pastor busca seu rebanho no dia em que está em meio de suas ovelhas espalhadas, assim buscarei minhas ovelhas, e as livrarei de todos os lugares por onde foram espalhadas, no dia de nuvem e de escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 13, 'E eu as tirarei dos povos, e as ajuntarei das terras; eu as trarei para sua terra, e as apascentarei nos montes de Israel, junto às correntes de águas, e em todas as habitações daquela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 14, 'Em bons pastos eu as apascentarei, e nos altos montes de Israel será sua pastagem; ali se deitarão em boa pastagem, e em prósperos pastos serão apascentadas sobre os montes de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 15, 'Eu apascentarei minhas ovelhas, e eu farei elas se deitarem [em segurança] , diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 16, 'Eu buscarei a perdida, e trarei de volta a desgarrada; porei curativo na que estiver ferida, e fortalecerei a enferma; mas a gorda e a forte destruirei. Eu as apascentarei com julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 17, 'E quanto a vós, ovelhas minhas, assim diz o Senhor DEUS: Eis que eu julgarei entre ovelha e ovelha, entre carneiros e bodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 18, 'Por acaso não vos basta que comais o bom pasto, para terdes que pisotear com vossos pés o resto de vossos pastos? E não vos basta as águas limpas, para sujardes o resto [das águas] com vossos pés?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 19, 'Minhas ovelhas terão de comer o que foi pisoteado por vossos pés, e beber o que foi sujo por vossos pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 20, 'Por isso assim lhes diz o Senhor DEUS: Eis que eu, eu mesmo, julgarei entre a ovelha gorda e a ovelha magra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 21, 'Porque empurrais com o lado e com o ombro, e com vossos chifres chifrais todas as fracas, até que as espalhais para fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 22, 'Portanto eu salvarei minhas ovelhas, para que nunca mais sirvam de saque; e julgarei entre ovelha e ovelha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 23, 'E levantarei sobre elas um pastor, e ele as apascentará: a meu servo Davi; ele as apascentará, e ele será o pastor delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 24, 'Eu, o SENHOR serei o Deus delas, e meu servo Davi será príncipe no meio delas. Eu, o SENHOR, falei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 25, 'E farei com elas um pacto de paz, e farei cessar os maus animais da terra; e habitarão no deserto em segurança, e dormirão nos bosques.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 26, 'E farei com que elas e os lugares ao redor de meu monte sejam bênção; e farei descer a chuva em seu tempo; chuvas de bênção serão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 27, 'E as árvores do campo darão seu fruto, e a terra dará seu produto, e estarão em segurança sobre sua terra; e saberão que eu sou o SENHOR, quando quebrar as varas de seu jugo, e as livrar da mão dos que se servem delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 28, 'E não [mais] servirão de presa às nações, nem as feras da terra as devorarão; pois habitarão em segurança, e não haverá quem [as] espante;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 29, 'E lhes despertarei uma plantação de renome, e não mais serão consumidos de fome na terra, nem serão mais envergonhadas pelas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 30, 'Assim saberão que eu, o SENHOR, seu Deus, estou com elas, e elas são o meu povo, a casa de Israel, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 34, 31, 'E vós, ovelhas minhas, sois ovelhas humanas do meu pasto; eu sou vosso Deus, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 2, 'Filho do homem, dirige teu rosto contra o monte de Seir, e profetiza contra ele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 3, 'E dize-lhe: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó monte de Seir; estenderei minha mão contra ti, e te tornarei em desolação e devastação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 4, 'Tornarei as tuas cidades em ruínas, e tu serás desolado; e saberás que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 5, 'Porque tiveste inimizade perpétua, e fizeste os filhos de Israel serem dispersos pelo poder da espada no tempo de sua aflição, no tempo do castigo final.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 6, 'Por isso, vivo eu, diz o Senhor DEUS, que eu te preparei para o sangue, e o sangue te perseguirá; dado que não odiaste o sangue, o sangue te perseguirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 7, 'E tornarei o monte de Seir em extrema desolação, e exterminarei quem passar [por ele] ,e quem voltar [por ele] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 8, 'E encherei seus montes de seus mortos; em teus morros, em teus vales, e em todas as tuas correntes de águas, cairão os mortos à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 9, 'Eu te tornarei em desolações perpétuas, e tuas cidades nunca mais serão habitadas; assim sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 10, 'Dado que disseste: As duas nações, as duas terras serão minhas, e delas tomaremos posse, ainda que o SENHOR ali estivesse;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 11, 'Por isso, vivo eu, diz o Senhor DEUS, que agirei conforme tua ira e conforme tua inveja com que agiste, por causa de teu ódio contra eles; e serei conhecido por entre eles, quando eu te julgar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 12, 'E saberás que eu, o SENHOR, ouvi todas as tuas blasfêmias que disseste contra os montes de Israel, dizendo: Já estão destruídos; já nos foram entregues para que os devoremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 13, 'Assim vos engradecestes contra mim com vossa boca, e multiplicastes vossas palavras contra mim. Eu ouvi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 14, 'Assim diz o Senhor DEUS: Enquanto toda a terra se alegrará, eu te tornarei em desolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 35, 15, 'Tal como te alegraste sobre a herança da casa de Israel, porque foi desolada, assim eu também farei a ti; o monte de Seir, e todo o Edom se tornarão em desolação; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 1, 'E tu, filho do homem, profetiza ao os montes de Israel, e dize: Ó montes de Israel, ouvi a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 2, 'Assim diz o Senhor DEUS: Dado que o inimigo disse sobre vós: Ha, ha! Até os antigos lugares altos se tornaram propriedade nossa!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 3, 'Portanto profetiza, e dize: Assim diz o Senhor DEUS: Por isso, por terem vos desolado e devorado desde o redor, para que fôsseis possuídos pelo resto das nações, e fostes trazidos aos lábios dos fofoqueiros, à infâmia do povo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 4, 'Por isso, ó montes de Israel, ouvi a palavra do Senhor DEUS: assim diz o Senhor DEUS aos montes e aos morros, às correntes e aos vales, às ruínas, aos lugares devastados, e às cidades abandonadas, que foram saqueadas e escarnecidas pelo resto das nações que há ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 5, 'Por isso assim diz o Senhor DEUS: Certamente no fogo do meu zelo falei contra o resto das nações, e contra todo Edom, que se apropriaram de minha terra por herança, com alegria de todo coração, com desprezo na alma, para que fosse saqueada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 6, 'Portanto profetiza sobre a terra de Israel, e dize aos montes, aos morros, às correntes, e aos vales: Assim diz o Senhor DEUS: Eis que falei em meu zelo e em meu furor, porque levastes sobre vós a humilhação das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 7, 'Por isso assim diz o Senhor DEUS: Eu prometo que as nações que estão ao redor de vós levarão sua humilhação sobre si mesmas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 8, 'Porém vós, ó montes de Israel, produzireis vossos ramos, e dareis vosso fruto a meu povo Israel; porque logo virão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 9, 'Porque eis que estou convosco; e me voltarei a vós, e sereis lavrados e semeados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 10, 'E farei multiplicar homens sobre vós, a toda a casa de Israel, a ela toda; e as cidades serão habitadas, e as ruínas serão reedificadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 11, 'E multiplicarei homens e animais sobre vós; e se multiplicarão, e crescerão; e vos farei habitar como no passado, e vos farei melhor que em vossos princípios; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 12, 'E farei andar homens sobre vós: o meu povo Israel; e eles te possuirão, e tu lhes serás sua herança, e nunca mais exterminarás seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 13, 'Assim diz o Senhor DEUS: Dado que dizem de vós: Tu és devoradora de homens, e exterminadora dos filhos de teu povo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 14, 'Por isso, não devorarás mais homens, e nem mais exterminarás os filhos de teus povos, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 15, 'E nunca mais te deixarei ouvir a vergonha dos povos, e nunca mais levarás sobre ti a humilhação das nações, nem mais exterminarás os filhos de teu povo, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 16, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 17, 'Filho do homem, quando a casa de Israel morava em sua terra, eles a contaminaram com seus caminhos e com suas ações; o caminho deles diante de mim foi como imundície de menstruada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 18, 'Por isso derramei minha ira sobre eles, por causa do sangue que derramaram sobre a terra, e por causa de seus ídolos com que a contaminaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 19, 'E os dispersei pelas nações, e foram espalhados pelas terras; eu os julguei conforme seus caminhos e conforme seus atos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 20, 'E quando chegaram às nações para onde foram, profanaram meu santo nome, pois deles se dizia: Estes são povo do SENHOR, e da terra dele saíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 21, 'Porém eu [os] poupei em favor a meu santo nome, o qual a casa de Israel profanou entre as nações para onde foram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 22, 'Portanto dize à casa de Israel: Assim diz o Senhor DEUS: Eu não faço [isso] por vós, ó casa de Israel, mas sim por causa de meu santo nome, o qual vós profanastes entre as nações para onde fostes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 23, 'Pois santificarei meu grande nome, que foi profanado entre as nações, o qual vós profanastes no meio delas; e as nações saberão que eu sou o SENHOR, diz o Senhor DEUS, quando eu for santificado em vós, diante de olhos delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 24, 'Porque eu vos tomarei das nações, e vos ajuntarei de todas as terras, e vos trarei para vossa própria terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 25, 'Então aspergirei água pura sobre vós, e sereis purificados; eu vos purificarei de todas vossas imundícies, e de todos os vossos ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 26, 'E vos darei um novo coração, e porei um novo espírito dentro de vós; e tirarei de vossa carne o coração de pedra, e vos darei um coração de carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 27, 'E porei meu Espírito dentro de vós, e farei com que andeis em meus estatutos, guardeis meus juízos, e [os] pratiqueis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 28, 'E habitareis na terra que dei a vossos pais; e vós sereis meu povo, e eu serei vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 29, 'E eu vos livrarei de todas as vossas imundícies; e chamarei ao trigo, e o multiplicarei, e não vos darei fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 30, 'Também multiplicarei o fruto dos árvores, e o produto do campo, para que nunca mais recebais a humilhação da fome entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 31, 'Então vos lembrareis de vossos maus caminhos, e de vossos atos que não foram bons; e tereis nojo de vós mesmos por vossas maldades, e por vossas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 32, 'Não faço [isto] por vós, diz o Senhor DEUS, notório vos seja; envergonhai-vos e humilhai-vos de vossos caminhos, ó casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 33, 'Assim diz o Senhor DEUS: No dia que vos purificar de todas as vossas maldades, então farei as cidades serem habitadas, e as ruínas serão reedificadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 34, 'E a terra assolada será lavrada, em lugar de ser assolada diante dos olhos de todos os que passavam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 35, 'E dirão: Esta terra que era assolada ficou como o jardim do Éden; e as cidades abandonadas, assoladas e arruinadas estão fortalecidas [e] habitadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 36, 'Então as nações que restarem ao vosso redor saberão que eu, o SENHOR, reedifico as [cidades] destruídas, e replanto as assoladas; eu, o SENHOR, falei e farei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 37, 'Assim diz o Senhor DEUS: Ainda permitirei serei buscado pela casa de Israel para lhes fazer isto: eu os multiplicarei de pessoas como a ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 36, 38, 'Tal como as ovelhas santificadas, como as ovelhas de Jerusalém em suas solenidades, assim também as cidades desertas serão cheias de rebanhos de pessoas; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 1, 'A mão do SENHOR veio sobre mim, e me tirou por meio do Espírito do SENHOR, e me pôs no meio de um vale que estava cheio de ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 2, 'E me fez passar perto deles ao redor; e eis que havia muitos sobre a face do vale, e eis que estavam sequíssimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 3, 'E perguntou-me: Filho do homem, por acaso viverão estes ossos? E eu respondi: Senhor DEUS, tu [o] sabes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 4, 'Então disse-me: Profetiza sobre estes ossos, e dize-lhes: Ossos secos, ouvi a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 5, 'Assim diz o Senhor DEUS a estes ossos: Eis que eu farei entrar espírito em vós, e vivereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 6, 'E porei nervos sobre vós, farei subir carne sobre vós, cobrirei de pele sobre vós, porei espírito em vós, e vivereis; e sabereis que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 7, 'Então profetizei como havia me sido mandado; e houve um ruído enquanto eu profetizava, e eis [que se fez] um tremor, e os ossos se aproximaram, cada osso a seu osso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 8, 'E olhei, e eis que [havia] nervos sobre eles, e a carne subiu, e a pele cobriu por cima deles; porém não havia espírito neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 9, 'Então me disse: Profetiza ao espírito, profetiza, ó filho do homem, e dize ao espírito: Assim diz o Senhor DEUS: Vem dos quatro ventos, ó espírito, e sopra sobre estes mortos, para que vivam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 10, 'E profetizei como havia me sido mandado; então o espírito entrou neles, e viveram, e se puseram de pé, um exército extremamente grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 11, 'Então me disse: Filho do homem, estes ossos são toda a casa de Israel. Eis que eles dizem: Nossos ossos se secaram, e nossa esperança pereceu; fomos exterminados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 12, 'Portanto profetiza, e dize-lhes: Assim diz o Senhor DEUS: Eis que eu abrirei vossos sepulturas, ó povo meu, e vos farei subir de vossas sepulturas, e vos trarei à terra de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 13, 'E sabereis que eu sou o SENHOR, quando eu abrir vossas sepulturas, e vos fizer subir de vossas sepulturas, ó povo meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 14, 'E porei meu espírito em vós, e vivereis, e vos porei em vossa terra; e sabereis que eu, o SENHOR, falei e fiz, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 15, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 16, 'Tu, pois, ó filho do homem, toma para ti agora uma vara de madeira, e escreve nela: A Judá, e aos filhos de Israel, seus companheiros. Toma para ti depois outra vara de madeira, e escreve nela: A José, vara de Efraim, e a toda a casa de Israel, seus companheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 17, 'E junta-as um à outra, para que sejam um para ti como uma só vara de madeira; e serão uma em tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 18, 'E quando te falarem os filhos de teu povo, dizendo: Por acaso não nos explicarás que tu [queres dizer] com isso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 19, '[Então] tu lhes dirás: Assim diz o Senhor DEUS: Eis que eu tomo a vara de José que esteve na mão de Efraim, e das tribos de Israel seus companheiros, e os juntarei com ele à vara de Judá, e as farei uma só vara, e serão uma minha mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 20, 'E as varas sobre as quais houverdes escrito estarão em tua mão diante dos olhos deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 21, 'Dize-lhes, pois: Assim diz o Senhor DEUS: Eis que eu tomarei os filhos de Israel dentre as nações para onde foram, e os ajuntarei desde os arredores e os trarei à sua [própria] terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 22, 'E deles farei uma nação na terra, nos montes de Israel; e um único rei será rei deles todos; e nunca mais serão duas nações, nem nunca mais serão divididos em dois reinos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 23, 'E nunca mais se contaminarão com seus ídolos, nem com suas abominações, nem com qualquer de suas transgressões; e os livrarei de todas as suas habitações em que pecaram, e os purificarei; assim eles serão meu povo, e eu serei o Deus deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 24, 'E meu servo Davi será rei sobre eles, e todos eles terão um [só] pastor; e andarão em meus juízos, guardarão meus estatutos, e os praticarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 25, 'E habitarão na terra que dei a meu servo Jacó, na qual vossos pais habitaram; e nela habitarão eles, seus filhos, e os filhos de seus filhos para sempre; e meu servo Davi será o príncipe deles eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 26, 'E farei com eles um pacto de paz; será um pacto perpétuo com eles; e os porei, e os multiplicarei, e porei meu santuário no meio deles para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 27, 'E com eles estará meu tabernáculo; serei o Deus deles, e ele serão meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 37, 28, 'E as nações saberão que eu, o SENHOR, santifico a Israel, quando meu santuário estiver no meio deles para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 1, 'E veio a mim a palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 2, 'Filho do homem, dirige teu rosto contra Gogue, da terra de Magogue, príncipe-chefe de Meseque e Tubal, e profetiza contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 3, 'E dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Gogue, príncipe-chefe de Meseque e de Tubal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 4, 'E eu te farei virar, e porei anzóis em tuas queixos, e te levarei com todo o teu exército, cavalos e cavaleiros, todos eles vestidos com armadura completa, uma grande multidão com escudos pequenos e grandes, todos eles manejando espada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 5, 'Persas, cuxitas, e os de Pute com eles; todos eles [com] escudo e capacete;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 6, 'Gômer, e todas as suas tropas; a casa de Togarma, dos lados do norte, e todas as suas tropas; muitos povos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 7, 'Prepara-te, e apronta-te, tu, e toda as tuas multidões que se juntaram a ti, e sê tu guardião delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 8, 'Depois de muitos dias serás tu visitado; ao fim de anos virás à terra que foi restaurada da espada, ajuntada de muitos povos, aos montes de Israel, que sempre serviram de assolação; mas aquele [povo] foi trazido das nações, e todos eles habitarão em segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 9, 'Então tu subirás, virás como uma tempestade devastadora; serás como nuvem para cobrir a terra, tu, todas as tuas tropas, e muitos povos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 10, 'Assim diz o Senhor DEUS: E será naquele dia, que subirão palavras em teu coração, e pensarás mau pensamento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 11, 'E dirás: Subirei contra terra das aldeias sem muros, virei contra os que estão em repouso, que habitam em segurança, todos eles habitam sem muros, não têm ferrolhos nem portas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 12, 'Para tomar despojo e para saquear presa; para virar tua mão contra as terras desertas [que agora] estão habitadas, e contra o povo que foi ajuntado das nações, que é dono de gados e de posses, que mora no meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 13, 'Seba, Dedã, os mercadores de Társis, e todos seus filhotes de leões te dirão: Por acaso vens para tomar despojos? Reuniste tua multidão para saquear presa, para lavar prata e ouro, para tomar gados e posses, para tomar grandes despojos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 14, 'Portanto profetiza, ó filho do homem, e dize a Gogue: Assim diz o Senhor DEUS: Por acaso naquele dia, quando meu povo Israel habitar em segurança, tu não o reconhecerás?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 15, 'Virás, pois, de teu lugar, das regiões do norte, tu e muitos povos contigo, todos eles a cavalo, uma grande reunião, e imenso exército;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 16, 'E subirás contra meu povo Israel como uma nuvem para cobrir a terra; [isto] será no fim dos dias; então eu te trarei contra minha terra, para que as nações me conheçam, quando eu houver me santificado em ti, ó Gogue, diante de seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 17, 'Assim diz o Senhor DEUS: Não és tu aquele de quem eu disse nos tempos passados, por meio dos meus servos, os profetas de Israel, que naqueles dias profetizaram [vários] anos que eu te traria contra eles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 18, 'Porém será naquele tempo, quando Gogue vier contra a terra de Israel, diz o Senhor DEUS, que minha fúria subirá ao meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 19, 'Porque falei em meu zelo, no fogo de minha ira, que naquele dia haverá grande tremor sobre a terra de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 20, '[De tal maneira] que diante de mim tremerão os peixes do mar, as aves do céu, os animais do campo, todos os répteis andam se arrastrando sobre a terra, e todos os seres humanos que estão sobre a face da terra; e os montes serão derrubados, os precipícios cairão, e todos os muros cairão por terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 21, 'Pois chamarei contra ele a espada em todos os meus montes, diz o Senhor DEUS; a espada de cada um será contra seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 22, 'E disputarei contra ele com pestilência e com sangue; e farei haver uma grande pancada de chuva, grandes pedras de granizo, fogo e enxofre sobre ele, sobre suas tropas, e sobre os muitos povos que estiverem com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 38, 23, 'Assim me engrandecerei e me santificarei, e serei conhecido em olhos de muitas nações; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 1, 'Tu pois, ó filho do homem, profetiza contra Gogue, e dize: Assim diz o Senhor DEUS: Eis que eu sou contra ti, ó Gogue, príncipe-chefe de Meseque e Tubal;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 2, 'Eu te virarei, te arrastarei, te farei subir das regiões do norte, e te trarei sobre os montes de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 3, 'Tirarei teu arco de tua mão esquerda, e farei cair tuas flechas de tua mão direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 4, 'Nos montes de Israel cairás tu, todas tuas tropas, e os povos que estão contigo; eu te dei como alimento para toda ave e todo pássaro de asas, e aos animais do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 5, 'Sobre a face do campo cairás; porque [assim] eu falei, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 6, 'E enviarei fogo em Magogue, e sobre os que habitam em segurança nas terras costeiras; e saberão que eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 7, 'E farei notório meu santo nome no meio de meu povo Israel, e nunca mais deixarei profanar meu santo nome; e as nações saberão que eu sou o SENHOR, o Santo em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 8, 'Eis que [isto] vem e acontecerá, diz o Senhor DEUS; este é o dia do qual tenho falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 9, 'E os moradores das cidades de Israel sairão, e acenderão fogo e queimarão armas, escudos grandes e pequenos, arcos, flechas, bastões de mão, e lanças; e as queimarão no fogo por sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 10, 'E não trarão lenha do campo, nem [a] cortarão dos bosques; em vez disso, queimarão as armas no fogo; e tomarão daqueles que deles tomaram, despojarão aos que os despojaram, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 11, 'E será naquele tempo, que ali darei a Gogue um lugar de sepultura em Israel, o vale dos que passam ao oriente do mar, e este será um obstáculo aos que passarem; e ali sepultarão a Gogue e a toda sua multidão; e o chamarão de “o vale da multidão de Gogue”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 12, 'E durante sete meses a casa de Israel os enterrará para purificar a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 13, 'Pois todo o povo do país os enterrará, e será notório para eles o dia [em que] eu for glorificado, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 14, 'E separarão homens para que continuamente percorram a terra [de Israel] , e enterrem aos passantes que restaram sobre a face da terra, para que purifiquem; ao fim de sete meses completarão a busca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 15, 'E os que passam pela terra, caso passem e vejam [algum] osso humano, levantará junto a ele um marco, até que os coveiros o enterrem no vale da multidão de Gogue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 16, 'E também o nome da cidade será Hamoná; assim purificarão a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 17, 'Tu, pois, ó filho do homem, assim diz o Senhor DEUS; Dize às aves, a todos os pássaros, e a todos os animais do campo: Ajuntai-vos, e vinde; reuni-vos de todas partes ao meu sacrifício que eu sacrifiquei por vós, um sacrifício grande nos montes de Israel; comei carne, e bebei sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 18, 'Comereis carne de guerreiros, e bebereis sangue de príncipes da terra; de carneiros, de cordeiros, de bodes, e de bezerros, todos eles cevados de Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 19, 'E comereis gordura até vos fartardes, e bebereis sangue até vos embebedardes, do meu sacrifício que eu sacrifiquei por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 20, 'E vos fartareis à minha mesa, de cavalos, de cavaleiros, de guerreiros, e de todos os homens de guerra, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 21, 'E porei minha glória entre as nações; e todas as nações verão meu julgamento que fiz, e minha mão que pus sobre elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 22, 'E daquele dia em diante a casa de Israel saberá que eu sou o SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 23, 'E as nações saberão que os da casa de Israel foram levados ao cativeiro por sua [própria] maldade, porque se rebelaram contra mim; então escondi meu rosto deles, e os entreguei na mão de seus adversários, e todos caíram à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 24, 'Conforme a imundície deles e conforme suas rebeliões eu fiz com eles; e deles escondi meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 25, 'Portanto assim diz o Senhor DEUS: Agora restaurarei Jacó de seu infortúnio, terei misericórdia de toda a casa de Israel, e zelarei por meu santo nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 26, 'Quando eles tiverem levado sobre si sua vergonha, e toda sua rebeldia com que se rebelaram contra mim, quando habitarem seguros em sua terra, e não houver quem os espante;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 27, 'Quando eu trouxé-los de volta dos povos, e os juntar das terras de seus inimigos, e for eu santificado neles diante dos olhos de muitas nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 28, 'Então saberão que eu sou o SENHOR seu Deus, porque eu os fiz serem levados em cativeiro entre as nações, e os ajuntarei de volta em sua terra, sem deixar mais nenhum deles lá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 39, 29, 'Nem esconderei mais deles meu rosto; pois derramarei meu Espírito sobre a casa de Israel, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 1, 'No vigésimo quinto ano de nosso cativeiro, no princípio do ano, aos dez do mês, aos catorze anos depois que a cidade foi ferida, naquele mesmo dia veio sobre mim a mão do SENHOR, e me levou para lá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 2, 'Em visões de Deus me levou à terra de Israel, e me pôs sobre um monte muito alto, sobre o qual havia como um edifício de uma cidade ao sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 3, 'E havendo me levado ali, eis um homem cuja aparência era como a aparência de bronze, e [tinha] um cordel de linho em sua mão, e uma cana de medir; e ele estava em pé à porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 4, 'E aquele homem me falou: Filho do homem, olha com teus olhos, ouve com teus ouvidos, e põe teu coração em tudo quanto eu te mostrar, pois foste trazido aqui para que eu te mostrasse. Anuncia, pois, à casa de Israel tudo o que vires.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 5, 'E eis, um muro fora do templo ao redor; e na mão daquele homem uma cana de medir de seis côvados, [cada côvado] de um côvado e um palmo; e mediu a largura do edifício de uma cana, e a altura, de outra cana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 6, 'Então ele veio à porta que estava voltada para o oriente, subiu por seus degraus, e mediu o umbral da porta de uma cana de largura, e o outro umbral de outra cana de largura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 7, 'E [cada] câmara tinha uma cana de comprimento, e uma cana de largo; e entre as câmaras eram cinco côvados; e o umbral da porta junto ao pórtico da porta por dentro, uma cana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 8, 'Também mediu o pórtico da porta por dentro, uma cana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 9, 'Então mediu o pórtico da porta, de oito côvados, e seus pilares de dois côvados; e o pórtico da porta por dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 10, 'E as câmaras pequenas da porta do oriente eram três de um lado e três do outro; todas as três de uma mesma medida; também os pilares de um lado e do outro [tinham] uma mesma medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 11, 'E mediu a largura da entrada da porta, de dez côvados; o comprimento do portal era de treze côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 12, 'E o espaço de diante das câmaras pequenas era de um côvado de um lado, e de um côvado do outro lado; e cada câmara tinha seis côvados de um lado, e seis côvados do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 13, 'Então mediu a porta desde o teto da uma câmara pequena até o teto da outra, vinte e cinco côvados de largura, porta contra porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 14, 'Também fez [medição com] os pilares de sessenta côvados, o pilar do pátio ao redor da porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 15, 'E desde a dianteira da porta de entrada até a dianteira do pórtico da porta interior havia cinquenta côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 16, 'Havia também janelas estreitas nas câmaras pequenas, e em seus pilares por dentro ao redor da porta, e assim também nos pórticos; e as janelas estavam ao redor por dentro; e em [cada] poste havia palmeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 17, 'Então me levou ao átrio exterior, e eis que havia [nele] câmaras, e um pavimento feito no pátio ao redor; trinta câmaras havia naquele pavimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 18, 'E o pavimento ao lado das portas era equivalente ao comprimento das portas ( [este era] o pavimento inferior).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 19, 'E mediu a largura desde a dianteira da porta inferior até a dianteira do pátio interior pelo lado de fora: cem côvados pelo oriente e pelo norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 20, 'E quanto à porta que estava voltada para o norte no átrio exterior, mediu seu comprimento e sua largura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 21, 'E suas câmaras pequenas eram três de um lado, e três de outro; e seus pilares e seus pórticos eram da mesma medida da primeira porta: cinquenta côvados era seu comprimento, e a largura era de vinte e cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 22, 'E suas janelas, e seu pórtico, e suas palmeiras, eram da medida da porta que estava voltada para o oriente; e subiam a ela por sete degraus; e seus alpendres eram diante deles.')
